input.new_string:
function counts(){
  return {
    all: items.filter(i=>!i.archived).length,
    toread: items.filter(i=>i.readLater && !i.archived).length,
    archived: items.filter(i=>i.archived).length,
  };
}
function renderViews(){
  const c=counts(); const bar=document.getElementById("views");
  const defs=[["all","All",c.all],["toread","To read",c.toread],["archived","Archived",c.archived]];
  bar.innerHTML="";
  defs.forEach(([k,label,n])=>{ const b=document.createElement("button"); b.className=(view===k?"on":""); b.innerHTML=label+' <span class="count">'+n+'</span>'; b.onclick=()=>{ view=k; render(); }; bar.appendChild(b); });
}
function visible(){
  if(view==="archived") return items.filter(i=>i.archived);
  if(view==="toread") return items.filter(i=>i.readLater && !i.archived);
  return items.filter(i=>!i.archived);
}
function render(justId){
  renderViews();
  listEl.innerHTML="";
  const vis=visible();
  if(vis.length===0){
    const msg = view==="toread" ? ["Nothing to read yet","Mark a saved link “Read later” and it shows up here."]
             : view==="archived" ? ["No archived links","Archive a link to tuck it away without deleting it."]
             : ["No bookmarks yet","Paste a link above to save your first one."];
    listEl.innerHTML='<div class="empty"><div class="big">'+msg[0]+'</div><div>'+msg[1]+'</div></div>';
    return;
  }
  vis.forEach(it=>{
    const card=document.createElement("div"); card.className="card"+(it.id===justId?" justadded":"");
    if(it.filling){ card.innerHTML='<div class="thumb none"></div><div class="body"><div class="filling">Getting details…</div></div>'; listEl.appendChild(card); return; }

