input.new_string:
const sub=document.createElement("div"); sub.className="sub"; sub.innerHTML='<span class="site">'+esc(it.site)+'</span> · saved '+(it.when||"just now");
body.appendChild(sub);
// actions: read-later toggle + archive/restore
const actions=document.createElement("div"); actions.className="actions";
if(!it.archived){
  const rl=document.createElement("button"); rl.className="act"+(it.readLater?" on":"");
  rl.textContent=(it.readLater?"🔖 To read":"🔖 Read later");
  rl.onclick=()=>{ it.readLater=!it.readLater; render(); };
  const ar=document.createElement("button"); ar.className="act"; ar.textContent="🗄 Archive";
  ar.onclick=()=>{ it.archived=true; render(); };
  actions.appendChild(rl); actions.appendChild(ar);
} else {
  const un=document.createElement("button"); un.className="act"; un.textContent="↩ Restore to list";
  un.onclick=()=>{ it.archived=false; render(); };
  actions.appendChild(un);
}
body.appendChild(actions);
card.innerHTML=thumb; card.appendChild(body);

