content.content:
1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1" />
6	<title>Bookmarks — prototype</title>
7	<style>
8	  :root { --bg:#f4f5f7; --card:#fff; --line:#e3e6ea; --muted:#6b7280; --faint:#9aa1ac; --accent:#2563eb; --accent-soft:#eff4ff; --chip:#eef2f7; }
9	  * { box-sizing: border-box; }
10	  body { margin:0; font-family: -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif; background:var(--bg); color:#1f2430; }
11	  header { background:var(--card); border-bottom:1px solid var(--line); padding:18px 24px; }
12	  header h1 { margin:0; font-size:19px; }
13	  header p { margin:4px 0 0; color:var(--muted); font-size:13px; }
14	  .wrap { max-width:760px; margin:0 auto; padding:24px; }
15	  .saver { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; }
16	  .saver .row { display:flex; gap:10px; }
17	  .saver input.url { flex:1; padding:11px 13px; border:1px solid var(--line); border-radius:8px; font-size:14px; }
18	  input:focus, textarea:focus { outline:2px solid var(--accent-soft); border-color:var(--accent); }
19	  .btn { padding:11px 18px; background:var(--accent); color:#fff; border:0; border-radius:8px; font-size:14px; font-weight:600; cursor:pointer; }
20	  .btn:disabled { opacity:.55; cursor:default; }
21	  .btn.sm { padding:6px 12px; font-size:13px; }
22	  .savefields { margin-top:12px; display:flex; flex-direction:column; gap:10px; }
23	  .lbl { font-size:11px; text-transform:uppercase; letter-spacing:.04em; color:var(--faint); margin-bottom:5px; }
24	  .noteinput { width:100%; border:1px solid var(--line); border-radius:8px; padding:9px 11px; font-size:13px; font-family:inherit; resize:vertical; }
25	  .hint { color:var(--muted); font-size:12px; margin:10px 2px 0; }
26	  .listhead { margin:26px 2px 10px; font-size:13px; color:var(--muted); text-transform:uppercase; letter-spacing:.04em; }
27	  .card { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; margin-bottom:12px; display:flex; gap:14px; }
28	  .card.justadded { animation: pop 1s ease; border-color:var(--accent); }
29	  @keyframes pop { 0%{background:var(--accent-soft);} 100%{background:var(--card);} }
30	  .thumb { flex:0 0 96px; width:96px; height:72px; border-radius:8px; overflow:hidden; background:#eef1f5; }
31	  .thumb img { width:100%; height:100%; object-fit:cover; display:block; }
32	  .thumb.none { display:none; }
33	  .body { flex:1; min-width:0; }
34	  .titlerow { display:flex; align-items:center; gap:8px; }
35	  .favi { flex:0 0 18px; width:18px; height:18px; border-radius:4px; }
36	  .title { font-size:15px; font-weight:600; color:#111827; text-decoration:none; }
37	  .title:hover { text-decoration:underline; }
38	  .desc { color:#3f4653; font-size:13px; margin-top:5px; line-height:1.45; }
39	  .note { color:#5b4636; background:#fff8ec; border:1px solid #f1e2c4; border-radius:7px; padding:6px 9px; font-size:12.5px; margin-top:8px; }
40	  .tags { position:relative; margin-top:9px; display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
41	  .chip { background:var(--chip); color:#374151; border-radius:999px; padding:3px 10px; font-size:12px; display:inline-flex; align-items:center; gap:6px; }
42	  .chip .x { cursor:pointer; color:var(--faint); font-weight:700; }
43	  .addtag, .addnote, .editnote { background:none; border:1px dashed var(--line); color:var(--muted); border-radius:999px; padding:3px 10px; font-size:12px; cursor:pointer; }
44	  .taginput { border:1px solid var(--accent); border-radius:999px; padding:4px 11px; font-size:12px; width:150px; }
45	  .suggest { position:absolute; z-index:5; background:#fff; border:1px solid var(--line); border-radius:8px; box-shadow:0 6px 18px rgba(0,0,0,.08); margin-top:4px; min-width:150px; overflow:hidden; }
46	  .suggest div { padding:7px 12px; font-size:13px; cursor:pointer; }
47	  .suggest div.act, .suggest div:hover { background:var(--accent-soft); color:var(--accent); }
48	  .suggest .new { color:var(--muted); }
49	  .sub { color:var(--faint); font-size:12px; margin-top:9px; }
50	  .sub .site { color:var(--muted); }
51	  .filling { color:var(--accent); font-size:14px; font-weight:500; }
52	  .views { max-width:760px; margin:0 auto; padding:14px 24px 0; display:flex; gap:8px; }
53	  .views button { background:#fff; border:1px solid var(--line); color:#374151; border-radius:999px; padding:6px 14px; font-size:13px; cursor:pointer; }
54	  .views button.on { background:var(--accent); color:#fff; border-color:var(--accent); }
55	  .views .count { opacity:.7; font-size:12px; margin-left:4px; }
56	  .actions { display:flex; gap:8px; margin-top:10px; }
57	  .act { background:none; border:1px solid var(--line); color:var(--muted); border-radius:7px; padding:4px 10px; font-size:12px; cursor:pointer; display:inline-flex; align-items:center; gap:5px; }
58	  .act.on { background:#fff7e6; border-color:#f0c66b; color:#8a6d1f; }
59	  .empty { text-align:center; color:var(--faint); padding:48px 20px; }
60	  .empty .big { font-size:15px; color:var(--muted); margin-bottom:6px; }
61	</style>
