63	<body>
64	<header>
65	  <h1>My Bookmarks</h1>
66	  <p>A personal place to save links and find them again.</p>
67	</header>
68	<div class="views" id="views"></div>
69	<div class="wrap">
70	  <div class="saver">
71	    <div class="row">
72	      <input class="url" id="url" type="text" placeholder="Paste a link to save…" autocomplete="off" />
73	      <button class="btn" id="save">Save</button>
74	    </div>
75	    <div class="savefields">
76	      <div>
77	        <div class="lbl">Tags (optional)</div>
78	        <div class="tags" id="saveTags"></div>
79	      </div>
80	      <div>
81	        <div class="lbl">Note (optional)</div>
82	        <textarea class="noteinput" id="saveNote" rows="2" placeholder="Why are you saving this?"></textarea>
83	      </div>
84	    </div>
85	    <div class="hint">Paste a link, optionally add tags and a note, then press Save. Tags suggest ones you already use.</div>
86	  </div>
87	
88	  <div class="listhead">Saved</div>
89	  <div id="list"></div>
90	</div>
