92	<script>
93	function ico(bg,g){ return 'data:image/svg+xml;utf8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="7" fill="'+bg+'"/><text x="16" y="22" font-family="Arial" font-size="18" font-weight="bold" fill="#fff" text-anchor="middle">'+g+'</text></svg>'); }
94	function prev(c1,c2,l){ return 'data:image/svg+xml;utf8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 192 144"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="'+c1+'"/><stop offset="1" stop-color="'+c2+'"/></linearGradient></defs><rect width="192" height="144" fill="url(#g)"/><text x="96" y="80" font-family="Arial" font-size="16" fill="#fff" opacity="0.9" text-anchor="middle">'+l+'</text></svg>'); }
95	const CANNED={
96	  "github.com":{title:"torvalds/linux: Linux kernel source tree",site:"GitHub",desc:"The official mirror of the Linux kernel source, maintained by Linus Torvalds and contributors.",icon:ico('#24292f','G'),preview:prev('#2b3137','#57606a','GitHub')},
97	  "nytimes.com":{title:"How Cities Are Rethinking Public Space",site:"The New York Times",desc:"Planners are turning parking lots and empty lots into parks, plazas and community gardens.",icon:ico('#000','T'),preview:prev('#4b6cb7','#182848','NYT')},
98	  "en.wikipedia.org":{title:"Photosynthesis — Wikipedia",site:"Wikipedia",desc:"The process by which green plants convert light energy into chemical energy stored in glucose.",icon:ico('#111','W'),preview:null},
99	  "medium.com":{title:"The Quiet Power of Note-Taking",site:"Medium",desc:"Why writing things down changes how you think, not just what you remember.",icon:ico('#000','M'),preview:prev('#3a3a3a','#111','Medium')},
100	};
101	function domainOf(raw){ try{ let u=new URL(raw.includes("://")?raw:"https://"+raw); return u.hostname.replace(/^www\./,""); }catch(e){ return null; } }
102	function titleCase(s){ return s.replace(/[-_]+/g," ").replace(/\b\w/g,c=>c.toUpperCase()); }
103	function guessMeta(raw){ const h=domainOf(raw); if(!h) return null; if(CANNED[h]) return CANNED[h];
104	  let site=titleCase(h.split(".")[0]); let title;
105	  try{ const u=new URL(raw.includes("://")?raw:"https://"+raw); const seg=u.pathname.split("/").filter(Boolean).pop(); title=seg?titleCase(decodeURIComponent(seg).replace(/\.\w+$/,""))+" — "+site:site+" — Home"; }catch(e){ title=site; }
106	  return {title,site,desc:"A page on "+site+". A short description is pulled from the page when available.",icon:ico('#2563eb',site.charAt(0).toUpperCase()),preview:null}; }
107	
108	let items=[
109	  { id:3, title:"A Field Guide to Getting Lost", site:"Longreads", desc:"Rebecca Solnit on wandering, uncertainty, and the value of not knowing where you are headed.", url:"https://longreads.com/field-guide", icon:ico('#e2574c','L'), preview:prev('#e2574c','#8a2b24','Longreads'), when:"2 days ago", tags:["reading","essays"], note:"", readLater:true, archived:false },
110	  { id:2, title:"CSS Grid: A Complete Guide", site:"CSS-Tricks", desc:"A comprehensive reference to every property in the CSS Grid layout module, with visual examples.", url:"https://css-tricks.com/snippets/css/complete-guide-grid", icon:ico('#ff7f50','C'), preview:null, when:"5 days ago", tags:["dev","reference"], note:"Bookmark for the grid layout at work.", readLater:false, archived:false },
111	  { id:1, title:"The Elements of Typographic Style", site:"Web", desc:"A page on Web. A short description is pulled from the page when available.", url:"https://webtypography.net", icon:ico('#2563eb','W'), preview:null, when:"3 weeks ago", tags:["design","reference"], note:"Kept for reference, done reading.", readLater:false, archived:true },
112	];
113	let nextId=4;
114	let view="all"; // all | toread | archived
115	const listEl=document.getElementById("list");
116	function esc(s){ return (s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
117	function allTags(){ const s=new Set(); items.forEach(it=>(it.tags||[]).forEach(t=>s.add(t))); return [...s].sort(); }
118	
119	// ---- reusable tag chip-input with suggestions ----
120	// container: element; getList: ()=>array; onchange: ()=>render
121	function mountTagInput(container, arr){
122	  container.innerHTML="";
123	  arr.forEach((t,i)=>{ const s=document.createElement("span"); s.className="chip"; s.innerHTML=esc(t)+' <span class="x">×</span>'; s.querySelector(".x").onclick=()=>{ arr.splice(i,1); mountTagInput(container,arr); }; container.appendChild(s); });
124	  const inp=document.createElement("input"); inp.className="taginput"; inp.placeholder="add tag…"; container.appendChild(inp);
125	  let sug=null, act=-1;
126	  function closeSug(){ if(sug){ sug.remove(); sug=null; act=-1; } }
127	  function add(t){ t=t.trim().replace(/,$/,""); if(t && !arr.includes(t)){ arr.push(t); } mountTagInput(container,arr); const ni=container.querySelector(".taginput"); if(ni) ni.focus(); }
128	  function showSug(){
129	    closeSug();
130	    const q=inp.value.trim().toLowerCase(); if(!q) return;
131	    const matches=allTags().filter(t=>t.toLowerCase().includes(q) && !arr.includes(t));
132	    sug=document.createElement("div"); sug.className="suggest";
133	    matches.slice(0,6).forEach((m,i)=>{ const d=document.createElement("div"); d.textContent=m; d.onmousedown=e=>{ e.preventDefault(); add(m); }; sug.appendChild(d); });
134	    const exact=allTags().some(t=>t.toLowerCase()===q);
135	    if(!exact){ const d=document.createElement("div"); d.className="new"; d.textContent='Create “'+inp.value.trim()+'”'; d.onmousedown=e=>{ e.preventDefault(); add(inp.value); }; sug.appendChild(d); }
136	    if(sug.children.length){ container.appendChild(sug); } else { closeSug(); }
137	  }
138	  inp.addEventListener("input", showSug);
139	  inp.addEventListener("keydown", e=>{
140	    const opts=sug?[...sug.children]:[];
141	    if(e.key==="ArrowDown"){ if(opts.length){ e.preventDefault(); act=(act+1)%opts.length; opts.forEach((o,i)=>o.classList.toggle("act",i===act)); } }
142	    else if(e.key==="ArrowUp"){ if(opts.length){ e.preventDefault(); act=(act-1+opts.length)%opts.length; opts.forEach((o,i)=>o.classList.toggle("act",i===act)); } }
143	    else if(e.key==="Enter"||e.key===","){ e.preventDefault(); if(act>=0&&opts[act]){ opts[act].dispatchEvent(new MouseEvent("mousedown")); } else if(inp.value.trim()){ add(inp.value); } }
144	    else if(e.key==="Escape"){ closeSug(); }
145	  });
146	  inp.addEventListener("blur", ()=>setTimeout(closeSug,120));
147	}
148	
149	let saveTags=[];
150	mountTagInput(document.getElementById("saveTags"), saveTags);
151	
152	function counts(){
153	  return {
154	    all: items.filter(i=>!i.archived).length,
155	    toread: items.filter(i=>i.readLater && !i.archived).length,
156	    archived: items.filter(i=>i.archived).length,
157	  };
158	}
159	function renderViews(){
160	  const c=counts(); const bar=document.getElementById("views");
161	  const defs=[["all","All",c.all],["toread","To read",c.toread],["archived","Archived",c.archived]];
162	  bar.innerHTML="";
163	  defs.forEach(([k,label,n])=>{ const b=document.createElement("button"); b.className=(view===k?"on":""); b.innerHTML=label+' <span class="count">'+n+'</span>'; b.onclick=()=>{ view=k; render(); }; bar.appendChild(b); });
164	}
165	function visible(){
166	  if(view==="archived") return items.filter(i=>i.archived);
167	  if(view==="toread") return items.filter(i=>i.readLater && !i.archived);
168	  return items.filter(i=>!i.archived);
169	}
170	function render(justId){
171	  renderViews();
172	  listEl.innerHTML="";
173	  const vis=visible();
174	  if(vis.length===0){
175	    const msg = view==="toread" ? ["Nothing to read yet","Mark a saved link “Read later” and it shows up here."]
176	             : view==="archived" ? ["No archived links","Archive a link to tuck it away without deleting it."]
177	             : ["No bookmarks yet","Paste a link above to save your first one."];
178	    listEl.innerHTML='<div class="empty"><div class="big">'+msg[0]+'</div><div>'+msg[1]+'</div></div>';
179	    return;
180	  }
181	  vis.forEach(it=>{
182	    const card=document.createElement("div"); card.className="card"+(it.id===justId?" justadded":"");
183	    if(it.filling){ card.innerHTML='<div class="thumb none"></div><div class="body"><div class="filling">Getting details…</div></div>'; listEl.appendChild(card); return; }
184	    const thumb=it.preview?'<div class="thumb"><img alt="" src="'+it.preview+'"></div>':'<div class="thumb none"></div>';
185	    const body=document.createElement("div"); body.className="body";
186	    body.innerHTML='<div class="titlerow"><img class="favi" alt="" src="'+it.icon+'"><a class="title" href="'+esc(it.url)+'" target="_blank" rel="noopener">'+esc(it.title)+'</a></div>'+
187	      '<div class="desc">'+esc(it.desc)+'</div>';
188	    // note
189	    const noteWrap=document.createElement("div");
190	    if(it._noteediting){ noteWrap.innerHTML='<div style="margin-top:8px;"><textarea class="noteinput" rows="2" placeholder="Why did you save this?">'+esc(it.note||"")+'</textarea><button class="btn sm" style="margin-top:6px;">Save note</button></div>';
191	      noteWrap.querySelector(".btn").onclick=()=>{ it.note=noteWrap.querySelector("textarea").value.trim(); it._noteediting=false; render(); }; }
192	    else if(it.note){ noteWrap.innerHTML='<div class="note">📝 '+esc(it.note)+' <span class="editnote" style="margin-left:6px;">edit</span></div>'; noteWrap.querySelector(".editnote").onclick=()=>{ it._noteediting=true; render(); }; }
193	    else { noteWrap.innerHTML='<div style="margin-top:8px;"><button class="addnote">＋ Note</button></div>'; noteWrap.querySelector(".addnote").onclick=()=>{ it._noteediting=true; render(); }; }
194	    body.appendChild(noteWrap);
195	    // tags (editable, with suggestions)
196	    const tagsWrap=document.createElement("div"); tagsWrap.className="tags";
197	    body.appendChild(tagsWrap);
198	    mountTagInput(tagsWrap, it.tags);
199	    const sub=document.createElement("div"); sub.className="sub"; sub.innerHTML='<span class="site">'+esc(it.site)+'</span> · saved '+(it.when||"just now");
200	    body.appendChild(sub);
201	    // actions: read-later toggle + archive/restore
202	    const actions=document.createElement("div"); actions.className="actions";
203	    if(!it.archived){
204	      const rl=document.createElement("button"); rl.className="act"+(it.readLater?" on":"");
205	      rl.textContent=(it.readLater?"🔖 To read":"🔖 Read later");
206	      rl.onclick=()=>{ it.readLater=!it.readLater; render(); };
207	      const ar=document.createElement("button"); ar.className="act"; ar.textContent="🗄 Archive";
208	      ar.onclick=()=>{ it.archived=true; render(); };
209	      actions.appendChild(rl); actions.appendChild(ar);
210	    } else {
211	      const un=document.createElement("button"); un.className="act"; un.textContent="↩ Restore to list";
212	      un.onclick=()=>{ it.archived=false; render(); };
213	      actions.appendChild(un);
214	    }
215	    body.appendChild(actions);
216	    card.innerHTML=thumb; card.appendChild(body);
217	    listEl.appendChild(card);
218	  });
219	}
220	
221	const input=document.getElementById("url"), saveBtn=document.getElementById("save");
222	function doSave(){
223	  const raw=input.value.trim(); if(!raw) return; const meta=guessMeta(raw); if(!meta){ input.focus(); return; }
224	  saveBtn.disabled=true;
225	  const full=raw.includes("://")?raw:"https://"+raw;
226	  const item={ id:nextId++, url:full, when:"just now", filling:true, tags:saveTags.slice(), note:document.getElementById("saveNote").value.trim(), readLater:false, archived:false };
227	  if(view!=="all"){ view="all"; }
228	  items.unshift(item); render();
229	  setTimeout(()=>{
230	    item.title=meta.title; item.site=meta.site; item.desc=meta.desc; item.icon=meta.icon; item.preview=meta.preview; item.filling=false;
231	    render(item.id);
232	    input.value=""; saveBtn.disabled=false;
233	    saveTags=[]; mountTagInput(document.getElementById("saveTags"), saveTags);
234	    document.getElementById("saveNote").value="";
235	  },700);
236	}
237	saveBtn.addEventListener("click",doSave);
238	input.addEventListener("keydown",e=>{ if(e.key==="Enter") doSave(); });
239	
240	render();
241	document.body.setAttribute("data-harness-ready","true");
242	</script>
243	</body>
244	</html>
