const input=document.getElementById("url"), saveBtn=document.getElementById("save");
function doSave(){
  const raw=input.value.trim(); if(!raw) return; const meta=guessMeta(raw); if(!meta){ input.focus(); return; }
  saveBtn.disabled=true;
  const full=raw.includes("://")?raw:"https://"+raw;
  const item={ id:nextId++, url:full, when:"just now", filling:true, tags:saveTags.slice(), note:document.getElementById("saveNote").value.trim(), readLater:false, archived:false };
  if(view!=="all"){ view="all"; }
  items.unshift(item); render();
  setTimeout(()=>{
    item.title=meta.title; item.site=meta.site; item.desc=meta.desc; item.icon=meta.icon; item.preview=meta.preview; item.filling=false;
    render(item.id);
    input.value=""; saveBtn.disabled=false;
    saveTags=[]; mountTagInput(document.getElementById("saveTags"), saveTags);
    document.getElementById("saveNote").value="";
  },700);
}

