vis.forEach(it=>{
  const card=document.createElement("div"); card.className="card"+(it.id===justId?" justadded":"");
  if(it.filling){ card.innerHTML='<div class="thumb none"></div><div class="body"><div class="filling">Getting details…</div></div>'; listEl.appendChild(card); return; }
  const thumb=it.preview?'<div class="thumb"><img alt="" src="'+it.preview+'"></div>':'<div class="thumb none"></div>';
  const body=document.createElement("div"); body.className="body";
  const descHtml = it.desc ? esc(it.desc) : (it.failed ? '<span class="nodesc">No description could be read for this page.</span>' : '');
  body.innerHTML='<div class="titlerow"><img class="favi" alt="" src="'+it.icon+'"><a class="title" href="'+esc(it.url)+'" target="_blank" rel="noopener">'+esc(it.title)+'</a></div>'+
    '<div class="desc">'+descHtml+'</div>';
  // note
  const noteWrap=document.createElement("div");
  if(it._noteediting){ noteWrap.innerHTML='<div style="margin-top:8px;"><textarea class="noteinput" rows="2" placeholder="Why did you save this?">'+esc(it.note||"")+'</textarea><button class="btn sm" style="margin-top:6px;">Save note</button></div>';
    noteWrap.querySelector(".btn").onclick=()=>{ it.note=noteWrap.querySelector("textarea").value.trim(); it._noteediting=false; render(); }; }
  else if(it.note){ noteWrap.innerHTML='<div class="note">📝 '+esc(it.note)+' <span class="editnote" style="margin-left:6px;">edit</span></div>'; noteWrap.querySelector(".editnote").onclick=()=>{ it._noteediting=true; render(); }; }
  else { noteWrap.innerHTML='<div style="margin-top:8px;"><button class="addnote">＋ Note</button></div>'; noteWrap.querySelector(".addnote").onclick=()=>{ it._noteediting=true; render(); }; }
  body.appendChild(noteWrap);
  // tags (editable, with suggestions)
  const tagsWrap=document.createElement("div"); tagsWrap.className="tags";
  body.appendChild(tagsWrap);
  mountTagInput(tagsWrap, it.tags);
  const sub=document.createElement("div"); sub.className="sub"; sub.innerHTML='<span class="site">'+esc(it.site)+'</span> · saved '+(it.when||"just now");
  body.appendChild(sub);
  // actions: read-later toggle + archive/restore
  const actions=document.createElement("div"); actions.className="actions";
  if(!it.archived){
    const rl=document.createElement("button"); rl.className="act"+(it.readLater?" on":"");
    rl.textContent=(it.readLater?"🔖 To read":"🔖 Read later");
    rl.onclick=()=>{ it.readLater=!it.readLater; render(); };
    const ar=document.createElement("button"); ar.className="act"; ar.textContent="🗄 Archive";
    ar.onclick=()=>{ it.archived=true; render(); };
    actions.appendChild(rl); actions.appendChild(ar);
  } else {
    const un=document.createElement("button"); un.className="act"; un.textContent="↩ Restore to list";
    un.onclick=()=>{ it.archived=false; render(); };
    actions.appendChild(un);
  }
  body.appendChild(actions);
  card.innerHTML=thumb; card.appendChild(body);

