function sortList(arr){
  const a=arr.slice();
  if(sortBy==="newest") a.sort((x,y)=>y.savedAt-x.savedAt);
  else if(sortBy==="oldest") a.sort((x,y)=>x.savedAt-y.savedAt);
  else if(sortBy==="title") a.sort((x,y)=>(x.title||x.url||"").toLowerCase().localeCompare((y.title||y.url||"").toLowerCase()));
  else if(sortBy==="updated") a.sort((x,y)=>y.updatedAt-x.updatedAt);
  return a;
}
function visible(){
  let base;
  if(view==="archived") base=items.filter(i=>i.archived);
  else if(view==="toread") base=items.filter(i=>i.readLater && !i.archived);
  else base=items.filter(i=>!i.archived);
  return sortList(base);
}

