    chip.onclick=(e)=>{ if(e.target.classList.contains("x")){ savedSearches.splice(i,1); render(); } else { applySaved(s); } };
    strip.appendChild(chip);
  });
}
function renderSaveRow(){
  const row=document.getElementById("saverow"); const cur=currentCriteria();
  const matches=savedSearches.some(s=>sameCriteria(cur,s));
  if(row._editing){
    row.innerHTML='<input id="ssname" placeholder="Name this search…"><button class="savebtn" id="ssok">Save</button><button class="savebtn" id="sscancel">Cancel</button>';
    const inp=row.querySelector("#ssname"); inp.value=suggestName(cur); inp.focus(); inp.select();
