    row.querySelector("#sscancel").onclick=()=>{ row._editing=false; render(); };
    inp.onkeydown=e=>{ if(e.key==="Enter") row.querySelector("#ssok").click(); if(e.key==="Escape") row.querySelector("#sscancel").click(); };
  } else {
    row.innerHTML='<button class="savebtn" id="savethis">★ Save this search</button><span class="desc"></span>';
