function captureCopy(it,quiet){ it._capturing=true; render(); setTimeout(()=>{ it._capturing=false; it.snapshot={ date:"just now", kind:isPdf(it.url)?"pdf":"page" }; render(); if(!quiet) showToast((isPdf(it.url)?'Saved the PDF of “':'Saved a full-page copy of “')+esc((it.title||it.url).slice(0,32))+'”'); },900); }
function archiveOrg(it){ it._archiving=true; render(); setTimeout(()=>{ it._archiving=false; it.archiveOrg={ date:"just now" }; render(); showToast('Preserved on the Internet Archive'); },1000); }
function archiveUrl(it){ return "https://web.archive.org/web/*/"+encodeURIComponent(it.url); }

