.toast .undo { color:#8ab4ff; font-weight:600; cursor:pointer; }
.iebar { max-width:760px; margin:12px auto 0; padding:0 24px; display:flex; gap:8px; }
.iebar button { background:#fff; border:1px solid var(--line); border-radius:8px; padding:8px 14px; font-size:13px; cursor:pointer; }
.iebar button:hover { border-color:var(--accent); color:var(--accent); }
.overlay { position:fixed; inset:0; background:rgba(20,24,34,.55); display:none; align-items:flex-start; justify-content:center; z-index:30; padding:40px 16px; overflow:auto; }
.overlay.on { display:flex; }
.modal { background:#fff; max-width:560px; width:100%; border-radius:12px; box-shadow:0 20px 60px rgba(0,0,0,.3); overflow:hidden; }
.modal .head { padding:16px 20px; border-bottom:1px solid var(--line); display:flex; align-items:center; }
.modal .head h2 { margin:0; font-size:16px; flex:1; }
.modal .head .close { border:0; background:none; font-size:20px; color:var(--muted); cursor:pointer; }
