// ---------------- Import / Export ----------------
const SAMPLE=[
  {folder:"Work", links:[{title:"torvalds/linux",url:"https://github.com/torvalds/linux"},{title:"MDN Web Docs",url:"https://developer.mozilla.org"}]},
  {folder:"Recipes", links:[{title:"No-knead bread",url:"https://cooking.example.com/no-knead-bread"},{title:"Weeknight pasta",url:"https://cooking.example.com/pasta"}]},
  {folder:"Reading", links:[{title:"CSS Grid: A Complete Guide",url:"https://css-tricks.com/snippets/css/complete-guide-grid"}]},
];
const ovl=document.getElementById("ovl"), modal=document.getElementById("modal");
function closeModal(){ ovl.classList.remove("on"); }
ovl.addEventListener("click", e=>{ if(e.target.id==="ovl") closeModal(); });
let parsed=null; // flat [{title,url,folder}]
function flatten(data){ const out=[]; data.forEach(f=>f.links.forEach(l=>out.push({title:l.title,url:l.url,folder:f.folder}))); return out; }
function parseNetscape(html){ const doc=new DOMParser().parseFromString(html,"text/html"); const out=[]; // walk H3(folder) then A links
  const nodes=doc.querySelectorAll("h3, a"); let cur="Imported";
  nodes.forEach(n=>{ if(n.tagName==="H3") cur=n.textContent.trim()||"Imported"; else if(n.tagName==="A" && n.href){ out.push({title:n.textContent.trim()||n.href, url:n.href, folder:cur}); } });
  return out;
}
function openImport(){
  ovl.classList.add("on");
  modal.innerHTML=
    '<div class="head"><h2>Import bookmarks</h2><button class="close">×</button></div>'+
    '<div class="bd"><p>Export your bookmarks from your browser (Chrome, Firefox, Safari or Edge) as an HTML file, then choose it here.</p>'+
      '<div class="filepick">Drop or choose your browser’s bookmarks file (.html)<br><input type="file" id="file" accept=".html,.htm" style="margin-top:10px;"><br><button class="btn sm" id="sample">Use a sample export instead</button></div>'+
    '</div>';
  modal.querySelector(".close").onclick=closeModal;
  modal.querySelector("#sample").onclick=()=>{ parsed=flatten(SAMPLE); showPreview(); };
  modal.querySelector("#file").onchange=(e)=>{ const f=e.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=()=>{ parsed=parseNetscape(r.result); showPreview(); }; r.readAsText(f); };
}
function showPreview(){
  const folders=[...new Set(parsed.map(p=>p.folder))];
  const dupCount=parsed.filter(p=>items.some(it=>normUrl(it.url)===normUrl(p.url))).length;
  modal.innerHTML=
    '<div class="head"><h2>Import preview</h2><button class="close">×</button></div>'+
    '<div class="bd"><p>Found <span class="big-n">'+parsed.length+'</span> bookmarks across <span class="big-n">'+folders.length+'</span> folders.</p>'+
      '<label class="opt"><input type="checkbox" id="foldertags" checked> Add each folder name as a tag</label>'+
      '<div class="folders" id="foldermap"></div>'+
      '<label class="opt"><input type="checkbox" id="skipdupes" checked> Skip links I’ve already saved ('+dupCount+' found)</label>'+
    '</div>'+
    '<div class="ft"><button class="btn sm" id="back">Back</button><button class="btn" id="doimport"></button></div>';
  modal.querySelector(".close").onclick=closeModal;
  modal.querySelector("#back").onclick=openImport;
  function refresh(){
    const ft=modal.querySelector("#foldertags").checked;
    const fm=modal.querySelector("#foldermap"); fm.innerHTML="";
    folders.forEach(f=>{ const r=document.createElement("div"); r.className="fr"; r.innerHTML='<span>📁 '+esc(f)+'</span><span class="tag">'+(ft?('#'+esc(f.toLowerCase().replace(/\s+/g,"-"))):'—')+'</span>'; fm.appendChild(r); });
    const skip=modal.querySelector("#skipdupes").checked;
    const willImport=skip? parsed.length-dupCount : parsed.length;
    modal.querySelector("#doimport").textContent="Import "+willImport+" bookmark"+(willImport===1?"":"s");
  }
  modal.querySelector("#foldertags").onchange=refresh;
  modal.querySelector("#skipdupes").onchange=refresh;
  refresh();
  modal.querySelector("#doimport").onclick=()=>{
    const ft=modal.querySelector("#foldertags").checked, skip=modal.querySelector("#skipdupes").checked;
    let n=0;
    parsed.forEach(p=>{ if(skip && items.some(it=>normUrl(it.url)===normUrl(p.url))) return;
      const m=guessMeta(p.url)||{}; const id=nextId++;
      const it={ id, url:p.url.includes("://")?p.url:"https://"+p.url, when:"just now", tags: ft?[p.folder.toLowerCase().replace(/\s+/g,"-")]:[], note:"", readLater:false, archived:false,
        title: (m.title&&!m.failed)? m.title : (p.title||p.url), desc:(m.desc&&!m.failed)?m.desc:"", site:m.site||domainOf(p.url)||"", icon:m.icon||ico('#2563eb','?'), preview:m.preview||null };
      it.savedAt=it.updatedAt=id; items.unshift(it); n++;
    });
    closeModal(); render(); showToast("Imported "+n+" bookmark"+(n===1?"":"s"));
  };
}
function openExport(){
  ovl.classList.add("on");
  const total=items.length;
  modal.innerHTML=
    '<div class="head"><h2>Export</h2><button class="close">×</button></div>'+
    '<div class="bd"><p>Export your <span class="big-n">'+total+'</span> bookmarks.</p>'+
      '<label class="radio"><input type="radio" name="fmt" value="html" checked> Browser bookmarks file (.html) — re-importable into any browser</label>'+
      '<label class="radio"><input type="radio" name="fmt" value="backup"> Full backup (.json) — includes tags, notes, read-later &amp; archive state</label>'+
    '</div>'+
    '<div class="ft"><button class="btn" id="download">Download</button></div>';
  modal.querySelector(".close").onclick=closeModal;
  modal.querySelector("#download").onclick=()=>{
    const fmt=modal.querySelector('input[name="fmt"]:checked').value;
    let blob, name;
    if(fmt==="html"){
      const rows=items.map(it=>'    <DT><A HREF="'+esc(it.url)+'">'+esc(it.title||it.url)+'</A>').join("\n");
      blob=new Blob(['<!DOCTYPE NETSCAPE-Bookmark-file-1>\n<DL><p>\n'+rows+'\n</DL><p>'],{type:"text/html"}); name="bookmarks.html";
    } else {
      blob=new Blob([JSON.stringify(items.map(({icon,preview,...rest})=>rest),null,2)],{type:"application/json"}); name="bookmarks-backup.json";
    }
    const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=name; document.body.appendChild(a); a.click(); a.remove();
    closeModal(); showToast("Exported "+items.length+" bookmarks as "+name);
  };
}
document.getElementById("importBtn").addEventListener("click", openImport);
document.getElementById("exportBtn").addEventListener("click", openExport);

render();
document.body.setAttribute("data-harness-ready","true");

