    '<div class="bd"><p>Export your <span class="big-n">'+total+'</span> bookmarks.</p>'+
      '<label class="radio"><input type="radio" name="fmt" value="html" checked> Browser bookmarks file (.html) — re-importable into any browser</label>'+
      '<label class="radio"><input type="radio" name="fmt" value="backup"> Full backup (.json) — includes tags, notes, read-later &amp; archive state</label>'+
    '</div>'+
    '<div class="ft"><button class="btn" id="download">Download</button></div>';
  modal.querySelector(".close").onclick=closeModal;
  modal.querySelector("#download").onclick=()=>{
    const fmt=modal.querySelector('input[name="fmt"]:checked').value;
    let blob, name;
    if(fmt==="html"){
      const rows=items.map(it=>'    <DT><A HREF="'+esc(it.url)+'">'+esc(it.title||it.url)+'</A>').join("\n");
      blob=new Blob(['<!DOCTYPE NETSCAPE-Bookmark-file-1>\n<DL><p>\n'+rows+'\n</DL><p>'],{type:"text/html"}); name="bookmarks.html";
    } else {
      blob=new Blob([JSON.stringify(items.map(({icon,preview,...rest})=>rest),null,2)],{type:"application/json"}); name="bookmarks-backup.json";
    }
    const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=name; document.body.appendChild(a); a.click(); a.remove();
    closeModal(); showToast("Exported "+items.length+" bookmarks as "+name);
  };
}
