/* dark theme */
body.dark { --bg:#12151c; --card:#1b2029; --line:#2a313d; --muted:#9aa4b2; --faint:#6b7482; --accent:#5b8cff; --accent-soft:#20293b; --chip:#252c38; color:#e6e9ef; }
body.dark header { background:#1b2029; }
body.dark .title { color:#f0f3f8; }
body.dark .desc { color:#c4ccd8; }
body.dark .note { background:#2a2417; border-color:#4a3f22; color:#e8d9b0; }
body.dark select, body.dark .search, body.dark input, body.dark textarea { background:#151a22; color:#e6e9ef; }
/* compact density */
body.compact .card { padding:9px 12px; gap:10px; }
body.compact .thumb { width:64px; height:48px; flex-basis:64px; }
body.compact .desc { -webkit-line-clamp:2; }
