body.nopreview .thumb { display:none !important; }
.overlay { position:fixed; inset:0; background:rgba(20,24,34,.55); display:none; align-items:flex-start; justify-content:center; z-index:30; padding:50px 16px; overflow:auto; }
.overlay.on { display:flex; }
.modal { background:var(--card); color:inherit; max-width:480px; width:100%; border-radius:12px; box-shadow:0 20px 60px rgba(0,0,0,.35); overflow:hidden; }
.modal .head { padding:16px 20px; border-bottom:1px solid var(--line); display:flex; align-items:center; }
.modal .head h2 { margin:0; font-size:16px; flex:1; }
.modal .head .close { border:0; background:none; font-size:20px; color:var(--muted); cursor:pointer; }
.modal .bd { padding:8px 20px 18px; }
