// ---------------- Display preferences ----------------
const prefs={ theme:"light", density:"comfortable", showPreview:true, defaultView:"all", defaultSort:"newest", autoCopy:false };
function applyPrefs(){
  document.body.classList.toggle("dark", prefs.theme==="dark" || (prefs.theme==="system" && window.matchMedia && matchMedia("(prefers-color-scheme: dark)").matches));
  document.body.classList.toggle("compact", prefs.density==="compact");
  document.body.classList.toggle("nopreview", !prefs.showPreview);
}
const ovl=document.getElementById("ovl"), modal=document.getElementById("modal");
function closePrefs(){ ovl.classList.remove("on"); }
ovl.addEventListener("click", e=>{ if(e.target.id==="ovl") closePrefs(); });
function seg(name, val, opts){ return '<div class="seg">'+opts.map(([v,l])=>'<button data-'+name+'="'+v+'" class="'+(val===v?"on":"")+'">'+l+'</button>').join("")+'</div>'; }
function openPrefs(){
  ovl.classList.add("on");
  modal.innerHTML=
    '<div class="head"><h2>Preferences</h2><button class="close">×</button></div>'+
    '<div class="bd">'+
      '<div class="prefgrp"><div class="lbl2">Appearance</div>'+seg("theme",prefs.theme,[["light","Light"],["dark","Dark"],["system","Match system"]])+'</div>'+
      '<div class="prefgrp"><div class="lbl2">List density</div>'+seg("density",prefs.density,[["comfortable","Comfortable"],["compact","Compact"]])+'</div>'+
      '<div class="prefgrp"><div class="prefrow"><span>Show preview images</span>'+seg("showpv",prefs.showPreview?"on":"off",[["on","On"],["off","Off"]])+'</div></div>'+
      '<div class="prefgrp"><div class="prefrow"><span>Open to</span><select id="pv-view"><option value="all">All</option><option value="toread">To read</option></select></div>'+
        '<div class="prefrow"><span>Default sort</span><select id="pv-sort"><option value="newest">Newest saved</option><option value="oldest">Oldest saved</option><option value="title">Title A–Z</option><option value="updated">Recently updated</option></select></div></div>'+
      '<div class="prefgrp"><div class="prefrow"><span>Automatically save a full-page copy of new bookmarks</span>'+seg("autocopy",prefs.autoCopy?"on":"off",[["on","On"],["off","Off"]])+'</div></div>'+
    '</div>';
  modal.querySelector(".close").onclick=closePrefs;
  modal.querySelectorAll("[data-theme]").forEach(bn=>bn.onclick=()=>{ prefs.theme=bn.dataset.theme; applyPrefs(); openPrefs(); });
  modal.querySelectorAll("[data-density]").forEach(bn=>bn.onclick=()=>{ prefs.density=bn.dataset.density; applyPrefs(); openPrefs(); });
  modal.querySelectorAll("[data-showpv]").forEach(bn=>bn.onclick=()=>{ prefs.showPreview=(bn.dataset.showpv==="on"); applyPrefs(); openPrefs(); });
  modal.querySelectorAll("[data-autocopy]").forEach(bn=>bn.onclick=()=>{ prefs.autoCopy=(bn.dataset.autocopy==="on"); openPrefs(); });
  const pvv=modal.querySelector("#pv-view"); pvv.value=prefs.defaultView; pvv.onchange=()=>{ prefs.defaultView=pvv.value; view=pvv.value; render(); };
  const pvs=modal.querySelector("#pv-sort"); pvs.value=prefs.defaultSort; pvs.onchange=()=>{ prefs.defaultSort=pvs.value; sortBy=pvs.value; const s=document.getElementById("sort"); if(s) s.value=pvs.value; render(); };
}
document.getElementById("prefsBtn").addEventListener("click", openPrefs);
// apply defaults at load
view=prefs.defaultView; sortBy=prefs.defaultSort; document.getElementById("sort").value=prefs.defaultSort; applyPrefs();

render();
document.body.setAttribute("data-harness-ready","true");

