function esc(s){ return (s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
// Minimal, safe Markdown renderer (escape first, then apply a small subset).
function renderMarkdown(src){
  const lines=(src||"").replace(/\r\n?/g,"\n").split("\n");
  let html="", i=0;
  function inline(t){
    t=esc(t);
    t=t.replace(/`([^`]+)`/g,(m,c)=>'<code>'+c+'</code>');
    t=t.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
    t=t.replace(/(^|[^*])\*([^*]+)\*/g,'$1<em>$2</em>');
    t=t.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
    return t;
  }
  while(i<lines.length){
    let ln=lines[i];
    if(/^\s*```/.test(ln)){ let buf=[]; i++; while(i<lines.length && !/^\s*```/.test(lines[i])){ buf.push(esc(lines[i])); i++; } i++; html+='<pre><code>'+buf.join("\n")+'</code></pre>'; continue; }
    let h=ln.match(/^(#{1,3})\s+(.*)$/); if(h){ const n=h[1].length; html+='<h'+n+'>'+inline(h[2])+'</h'+n+'>'; i++; continue; }
    if(/^\s*>\s?/.test(ln)){ let buf=[]; while(i<lines.length && /^\s*>\s?/.test(lines[i])){ buf.push(inline(lines[i].replace(/^\s*>\s?/,""))); i++; } html+='<blockquote>'+buf.join("<br>")+'</blockquote>'; continue; }
    if(/^\s*[-*]\s+/.test(ln)){ let buf=[]; while(i<lines.length && /^\s*[-*]\s+/.test(lines[i])){ buf.push('<li>'+inline(lines[i].replace(/^\s*[-*]\s+/,""))+'</li>'); i++; } html+='<ul>'+buf.join("")+'</ul>'; continue; }
    if(/^\s*\d+\.\s+/.test(ln)){ let buf=[]; while(i<lines.length && /^\s*\d+\.\s+/.test(lines[i])){ buf.push('<li>'+inline(lines[i].replace(/^\s*\d+\.\s+/,""))+'</li>'); i++; } html+='<ol>'+buf.join("")+'</ol>'; continue; }
    if(/^\s*$/.test(ln)){ i++; continue; }
    // paragraph: gather consecutive non-blank, non-special lines
    let buf=[];
    while(i<lines.length && !/^\s*$/.test(lines[i]) && !/^(#{1,3})\s|^\s*[-*]\s|^\s*\d+\.\s|^\s*>|^\s*```/.test(lines[i])){ buf.push(inline(lines[i])); i++; }
    html+='<p>'+buf.join("<br>")+'</p>';
  }
  return html;
}

