input.content:
:root {
  --bg:#f4f5f7; --card:#ffffff; --line:#e3e6ea; --text:#1f2430; --muted:#6b7280;
  --faint:#9aa1ac; --accent:#2563eb; --accent-soft:#eff4ff; --chip:#eef2f7;
  --danger:#b91c1c; --danger-soft:#fff5f5; --warn:#8a6d1f; --warn-soft:#fff8ec; --warn-line:#f1e2c4;
  --ok:#1b6e3c; --ok-soft:#e7f6ec; --ok-line:#bfe6cc;
}
body.theme-dark {
  --bg:#12151c; --card:#1b2029; --line:#2a313d; --text:#e6e9ef; --muted:#9aa4b2;
  --faint:#6b7482; --accent:#5b8cff; --accent-soft:#20293b; --chip:#252c38;
  --danger:#ff8a8a; --danger-soft:#2a1a1a; --warn:#e8d9b0; --warn-soft:#2a2417; --warn-line:#4a3f22;
  --ok:#7fd6a0; --ok-soft:#16261c; --ok-line:#2c4a37;
}
* { box-sizing:border-box; }
body { margin:0; font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif; background:var(--bg); color:var(--text); }
h1 { margin:0; font-size:20px; }
.tagline { margin:4px 0 0; color:var(--muted); font-size:13px; }
.app-header { background:var(--card); border-bottom:1px solid var(--line); padding:16px 24px; }
.hwrap, .wrap { max-width:780px; margin:0 auto; }
.hwrap { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; }
.wrap { padding:20px 24px 60px; }

.primary-btn { padding:11px 18px; background:var(--accent); color:#fff; border:0; border-radius:8px; font-size:14px; font-weight:600; cursor:pointer; }
.primary-btn:disabled { opacity:.5; cursor:default; }
.primary-btn.sm { padding:6px 12px; font-size:13px; }
.ghost-btn { background:var(--card); color:var(--text); border:1px solid var(--line); border-radius:8px; padding:8px 13px; font-size:13px; cursor:pointer; }
.ghost-btn:hover { border-color:var(--accent); color:var(--accent); }

input, textarea, select { font-family:inherit; color:var(--text); background:var(--card); }
input:focus, textarea:focus, select:focus { outline:2px solid var(--accent-soft); border-color:var(--accent); }

.saver { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; }
.saver-row { display:flex; gap:10px; }
.url-input { flex:1; padding:11px 13px; border:1px solid var(--line); border-radius:8px; font-size:14px; }
.saver-fields { margin-top:12px; display:flex; flex-direction:column; gap:10px; }
.field-label { font-size:11px; text-transform:uppercase; letter-spacing:.04em; color:var(--faint); margin-bottom:5px; }
.note-input { width:100%; border:1px solid var(--line); border-radius:8px; padding:9px 11px; font-size:13px; resize:vertical; }
.hint { color:var(--muted); font-size:12px; margin-top:10px; }
.save-msg { margin-top:10px; font-size:13px; border-radius:8px; padding:9px 12px; }
.save-msg.err { background:var(--danger-soft); border:1px solid var(--danger); color:var(--danger); }
.save-msg.warn { background:var(--warn-soft); border:1px solid var(--warn-line); color:var(--warn); }
.save-msg .link { text-decoration:underline; cursor:pointer; font-weight:600; }

.tag-input { position:relative; display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
.chip { background:var(--chip); color:var(--text); border-radius:999px; padding:3px 10px; font-size:12px; display:inline-flex; align-items:center; gap:6px; }
.chip .x { cursor:pointer; color:var(--faint); font-weight:700; }
.chip.clickable { cursor:pointer; }
.chip.clickable:hover { color:var(--accent); }
.chip.on { background:var(--accent); color:#fff; }
.tag-entry { border:1px solid var(--accent); border-radius:999px; padding:4px 11px; font-size:12px; width:150px; }
.suggest { position:absolute; z-index:10; background:var(--card); border:1px solid var(--line); border-radius:8px; box-shadow:0 6px 18px rgba(0,0,0,.12); margin-top:4px; min-width:160px; overflow:hidden; }
.suggest div { padding:7px 12px; font-size:13px; cursor:pointer; }
.suggest div.active, .suggest div:hover { background:var(--accent-soft); color:var(--accent); }
.suggest .new { color:var(--muted); }

.views { display:flex; gap:8px; margin:16px 0 0; flex-wrap:wrap; }
.views button { background:var(--card); border:1px solid var(--line); color:var(--text); border-radius:999px; padding:6px 14px; font-size:13px; cursor:pointer; }
.views button.on { background:var(--accent); color:#fff; border-color:var(--accent); }
.views .count { opacity:.7; font-size:12px; margin-left:5px; }

.saved-strip { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin-top:12px; }
.saved-strip .lbl { font-size:12px; color:var(--faint); }
.saved-chip { display:inline-flex; align-items:center; gap:7px; background:var(--card); border:1px solid var(--line); border-radius:999px; padding:5px 12px; font-size:13px; cursor:pointer; }
.saved-chip:hover { border-color:var(--accent); color:var(--accent); }
.saved-chip.active { background:var(--accent); color:#fff; border-color:var(--accent); }
.saved-chip .star { color:#f0b429; } .saved-chip.active .star { color:#fff; }
.saved-chip .x { color:var(--faint); font-weight:700; } .saved-chip.active .x { color:#dbe7ff; }

.findbar { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; margin-top:16px; }
.search { width:100%; padding:10px 13px; border:1px solid var(--line); border-radius:8px; font-size:14px; }
.search.bad { border-color:var(--danger); background:var(--danger-soft); }
.syntax { font-size:12px; color:var(--faint); margin-top:7px; }
.syntax.bad { color:var(--danger); }
.syntax code { background:var(--chip); border-radius:4px; padding:1px 5px; }
.tag-filter { margin-top:12px; display:flex; flex-wrap:wrap; gap:7px; align-items:center; }
.tag-filter .lbl { font-size:12px; color:var(--faint); margin-right:2px; }
.fchip { background:var(--chip); color:var(--text); border-radius:999px; padding:4px 12px; font-size:12px; cursor:pointer; border:1px solid transparent; }
.fchip.on { background:var(--accent); color:#fff; }
.save-search-row { margin-top:12px; display:flex; gap:8px; align-items:center; }
.save-search-row .desc { font-size:12px; color:var(--faint); }
.save-search-row input { border:1px solid var(--accent); border-radius:8px; padding:7px 11px; font-size:13px; width:200px; }

.toolbar { display:flex; align-items:center; justify-content:space-between; margin-top:18px; }
.tools-left { display:flex; gap:8px; }
.tools-right { display:flex; align-items:center; gap:8px; color:var(--faint); font-size:12px; }
.tools-right select { padding:6px 10px; border:1px solid var(--line); border-radius:8px; font-size:13px; }

.bulk-bar { position:sticky; top:0; z-index:15; background:#1f2430; color:#fff; border-radius:10px; padding:10px 14px; margin-top:14px; display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
body.theme-dark .bulk-bar { background:#0c0f14; }
.bulk-bar .cnt { font-weight:600; }
.bulk-bar button { background:#2b3342; color:#fff; border:1px solid #3a4256; border-radius:7px; padding:6px 11px; font-size:12.5px; cursor:pointer; }
.bulk-bar button:hover { background:#374156; }
.bulk-bar button.danger { color:#ffb4b4; }
.bulk-bar .spacer { flex:1; }
.bulk-bar .link { color:#8ab4ff; cursor:pointer; font-size:12.5px; }
.bulk-tag { position:relative; }
.bulk-tag input { border:1px solid #3a4256; background:#2b3342; color:#fff; border-radius:999px; padding:5px 11px; font-size:12.5px; width:150px; }
