:root {
  --bg:#f4f5f7; --card:#ffffff; --line:#e3e6ea; --text:#1f2430; --muted:#6b7280;
  --faint:#9aa1ac; --accent:#2563eb; --accent-soft:#eff4ff; --chip:#eef2f7;
  --danger:#b91c1c; --danger-soft:#fff5f5; --warn:#8a6d1f; --warn-soft:#fff8ec; --warn-line:#f1e2c4;
  --ok:#1b6e3c; --ok-soft:#e7f6ec; --ok-line:#bfe6cc;
}
body.theme-dark {
  --bg:#12151c; --card:#1b2029; --line:#2a313d; --text:#e6e9ef; --muted:#9aa4b2;
  --faint:#6b7482; --accent:#5b8cff; --accent-soft:#20293b; --chip:#252c38;
  --danger:#ff8a8a; --danger-soft:#2a1a1a; --warn:#e8d9b0; --warn-soft:#2a2417; --warn-line:#4a3f22;
  --ok:#7fd6a0; --ok-soft:#16261c; --ok-line:#2c4a37;
}
* { box-sizing:border-box; }
body { margin:0; font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif; background:var(--bg); color:var(--text); }
h1 { margin:0; font-size:20px; }
.tagline { margin:4px 0 0; color:var(--muted); font-size:13px; }
.app-header { background:var(--card); border-bottom:1px solid var(--line); padding:16px 24px; }
.hwrap, .wrap { max-width:780px; margin:0 auto; }
.hwrap { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; }
.wrap { padding:20px 24px 60px; }

.primary-btn { padding:11px 18px; background:var(--accent); color:#fff; border:0; border-radius:8px; font-size:14px; font-weight:600; cursor:pointer; }
.primary-btn:disabled { opacity:.5; cursor:default; }
.primary-btn.sm { padding:6px 12px; font-size:13px; }
