  [['all', 'All', c.all], ['toread', 'To read', c.toread], ['archived', 'Archived', c.archived]].forEach(([k, label, n]) => {
    const b = el('button', S.view === k ? 'on' : '', label + ' <span class="count">' + n + '</span>');
