  const pageItems = size === Infinity ? vis : vis.slice(start, start + size);
  pc.textContent = size === Infinity ? ('Showing all ' + vis.length) : ('Showing ' + (start + 1) + '–' + Math.min(start + size, vis.length) + ' of ' + vis.length);

